/bin/zsh -lc "env GIT_CONFIG_NOSYSTEM=1 GIT_CONFIG_GLOBAL=/dev/null /opt/homebrew/bin/python3 -c 'import sys,json; sys.path.insert(0,\"research\"); from central_probe_20825094 import group; rows=[]; bad=[]; worst=None
for a in [2,3,5,10,20,50,100,200,1000]:
 for r in [5,10,30,100,300,1000,3000]:
  for f in [0,0.01,0.05,0.1,0.25,0.5,0.75,0.9]:
   m=r+int(f*r)
   if m>2*r-2:continue
   val,count=group(a,r,m,q=False); row=[a,r,m,val];rows.append(row)
