   if worst is None or val<worst[-1]:worst=row
out=dict(status=\"floating exploratory comparison; not proof\",cases=len(rows),failures=bad,worst=worst);open(\"evidence/markov-73199834/qfree-central-probe.json\",\"w\").write(json.dumps(out,indent=2));print(json.dumps(dict(cases=len(rows),failure_count=len(bad),first_failures=bad[:8],worst=worst)))'"

